CREATE FUNCTION internal.parse_initial_qualified_codec(p_kind TEXT,p_text TEXT) RETURNS JSONB LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE v JSONB; s JSONB:=internal.initial_qualified_schema()->p_kind; cap INTEGER; phase INTEGER;
BEGIN
 cap:=CASE WHEN p_kind='assignment' THEN 65536 WHEN p_kind LIKE 'reply_%' THEN 524288 ELSE 131072 END;
 IF s IS NULL OR p_text IS NULL OR octet_length(p_text)>cap THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 BEGIN v:=p_text::JSONB; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END;
 IF internal.initial_canonical(v) IS DISTINCT FROM p_text OR NOT internal.initial_schema_matches(v,s) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 IF p_kind='reply_status' THEN
  phase:=array_position(ARRAY['allocated','verified','issued','output_registered','outcome_ready'],v->>'phase')-1;
  IF (v->'source'<>'null'::JSONB) IS DISTINCT FROM (phase>=1) OR (v->'execution_reference'<>'null'::JSONB) IS DISTINCT FROM (phase>=2) OR (v->'output'<>'null'::JSONB) IS DISTINCT FROM (phase>=3) OR (v->'result'<>'null'::JSONB) IS DISTINCT FROM (phase>=4) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 END IF;
 RETURN v;
END; $$;
CREATE FUNCTION internal.initial_qualified_context(p_candidate TEXT,p_assignment TEXT,p_preparation TEXT,p_installation TEXT,p_protocol TEXT,p_destination TEXT) RETURNS JSONB LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE a JSONB:=internal.parse_initial_qualified_codec('assignment',p_assignment); profile JSONB:=internal.parse_initial_media_profile(p_preparation); i JSONB:=internal.parse_initial_handoff_catalog('installation',p_installation); d JSONB:=internal.parse_initial_handoff_catalog('destination_backend',p_destination); h JSONB:=internal.parse_initial_handoff_profile(internal.initial_canonical(a#>'{handoff,profile}'),p_protocol);
BEGIN
 IF NOT internal.valid_initial_media_assignment_pair(p_candidate,internal.initial_canonical(jsonb_set(a-'handoff','{version}','2'))) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 PERFORM internal.assert_initial_media_profile_matches(p_candidate,p_preparation);
 PERFORM internal.assert_initial_handoff_catalog_envelope(p_preparation,internal.initial_canonical(h),p_protocol);
 IF a#>>'{handoff,profile_digest}' IS DISTINCT FROM internal.initial_handoff_digest('profile',internal.initial_canonical(h))
 OR a#>>'{handoff,installation_digest}' IS DISTINCT FROM internal.initial_handoff_catalog_digest('installation',p_installation)
 OR i->>'profile_digest' IS DISTINCT FROM a#>>'{handoff,profile_digest}' OR i->>'profile_generation' IS DISTINCT FROM h->>'generation'
 OR i->>'protocol_artifact_digest' IS DISTINCT FROM h->>'protocol_artifact_digest' OR i->>'copy_adapter_digest' IS DISTINCT FROM h->>'copy_adapter_digest' OR i->>'verification_adapter_digest' IS DISTINCT FROM h->>'verification_adapter_digest'
 OR i->>'preparation_profile_digest' IS DISTINCT FROM internal.initial_media_contract_digest('profile',p_preparation) OR a#>>'{preparation,profile_digest}' IS DISTINCT FROM i->>'preparation_profile_digest'
 OR i->>'source_backend_generation' IS DISTINCT FROM h->>'source_backend_generation' OR a#>>'{preparation,backend_generation}' IS DISTINCT FROM h->>'source_backend_generation'
 OR i->>'destination_backend_generation' IS DISTINCT FROM h->>'destination_backend_generation' OR d->>'generation' IS DISTINCT FROM h->>'destination_backend_generation'
 OR h->>'destination_backend_config_digest' IS DISTINCT FROM internal.initial_handoff_catalog_digest('destination_backend',p_destination) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 RETURN jsonb_build_object('assignment',a,'profile',profile,'assignment_digest',internal.initial_preparation_digest('assignment',p_assignment));
END; $$;
-- Context below is the output of initial_qualified_context, never service input.
-- It is declaration validation only; future owners must compare locked rows.
CREATE FUNCTION internal.assert_initial_qualified_grant(p_scan UUID,p_context JSONB,p_source_digest TEXT,p_expiry NUMERIC,p_text TEXT) RETURNS VOID LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE g JSONB:=internal.parse_initial_qualified_codec('grant',p_text); a JSONB:=p_context->'assignment'; profile JSONB:=p_context->'profile'; h JSONB:=a#>'{handoff,profile}'; wall BIGINT:=internal.initial_preparation_cohort_wall(a,profile); issue BIGINT:=(g->>'issued_at_ms')::BIGINT;
BEGIN
 PERFORM internal.assert_initial_execution_identity(p_scan,p_context->>'assignment_digest',jsonb_set(g,'{version}','1'));
 IF p_expiry IS NULL OR p_expiry::TEXT IN ('NaN','Infinity','-Infinity') OR p_expiry<>trunc(p_expiry) OR p_expiry<300000 OR p_expiry>9007199254740991
 OR g->>'source_digest' IS DISTINCT FROM p_source_digest OR g->>'profile_digest' IS DISTINCT FROM a#>>'{preparation,profile_digest}' OR g->>'artifact_digest' IS DISTINCT FROM profile#>>'{spec,artifact,sha256}'
 OR g->>'handoff_profile_digest' IS DISTINCT FROM a#>>'{handoff,profile_digest}' OR g->>'handoff_installation_digest' IS DISTINCT FROM a#>>'{handoff,installation_digest}' OR g->>'protocol_artifact_digest' IS DISTINCT FROM h->>'protocol_artifact_digest'
 OR (g->>'handoff_total_ms')::BIGINT<>(h->>'total_ms')::BIGINT OR (g->>'preparation_wall_ms')::BIGINT<>wall OR (g->>'preparation_expires_at_ms')::NUMERIC<>p_expiry
 OR (g->>'execution_deadline_ms')::BIGINT<>issue+5000+wall OR (g->>'registration_deadline_ms')::BIGINT<>issue+10000+wall OR (g->>'outcome_deadline_ms')::BIGINT<>issue+45000+wall
 OR issue<p_expiry-300000 OR issue+45000+wall+(h->>'total_ms')::BIGINT>=p_expiry THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
END; $$;
CREATE FUNCTION internal.assert_initial_qualified_source(p_scan UUID,p_context JSONB,p_text TEXT) RETURNS VOID LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE value JSONB; a JSONB; profile JSONB; item JSONB; source JSONB; facts JSONB; mapping JSONB; n INTEGER;
BEGIN
 value:=internal.parse_initial_preparation_execution('source_verification',p_text); a:=p_context->'assignment';
 profile:=p_context->'profile';
 PERFORM internal.assert_initial_execution_identity(p_scan,p_context->>'assignment_digest',value);
 IF value->>'profile_digest' IS DISTINCT FROM a#>>'{preparation,profile_digest}' OR value->>'backend_generation' IS DISTINCT FROM a#>>'{preparation,backend_generation}' OR value->>'validator_identity' IS DISTINCT FROM profile#>>'{spec,identities,validator}' OR jsonb_array_length(value->'entries')<>jsonb_array_length(a#>'{preparation,source_mapping}') THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 FOR item,n IN SELECT e,i::INTEGER-1 FROM jsonb_array_elements(value->'entries') WITH ORDINALITY v(e,i) LOOP
  mapping:=a#>ARRAY['preparation','source_mapping',n::TEXT]; source:=mapping->'source'; facts:=item->'facts';
  IF item->>'ordinal' IS DISTINCT FROM n::TEXT OR item->'object_id' IS DISTINCT FROM mapping->'object_id'
   OR item->'bytes' IS DISTINCT FROM jsonb_build_object('byte_count',source->'source_byte_count','sha256',source->'source_sha256','content_type',source->'source_content_type') THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  IF source->>'kind'='image' THEN
   IF facts->'image'='null'::JSONB OR facts->'wav'<>'null'::JSONB OR facts->'mp4'<>'null'::JSONB OR 'image/'||(facts#>>'{image,format}') IS DISTINCT FROM source->>'source_content_type' THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  ELSIF source->>'kind'='audio' THEN
   IF facts->'image'<>'null'::JSONB OR facts->'wav'='null'::JSONB OR facts->'mp4'<>'null'::JSONB OR (facts#>>'{wav,frames}')::BIGINT*(facts#>>'{wav,channels}')::BIGINT*(CASE facts#>>'{wav,format}' WHEN 'pcm16' THEN 2 ELSE 4 END)>(source->>'source_byte_count')::BIGINT THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  ELSE
   IF facts->'image'<>'null'::JSONB OR facts->'wav'<>'null'::JSONB OR facts->'mp4'='null'::JSONB THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  END IF;
 END LOOP;
END; $$;
CREATE FUNCTION internal.assert_initial_qualified_output(p_scan UUID,p_context JSONB,p_grant JSONB,p_text TEXT) RETURNS VOID LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE value JSONB; grant_value JSONB; a JSONB; profile JSONB; item JSONB; source JSONB; mapping JSONB; prepared JSONB; rule JSONB; n INTEGER; total BIGINT:=0;
BEGIN
 value:=internal.parse_initial_preparation_execution('output_manifest',p_text); a:=p_context->'assignment';
 PERFORM internal.assert_initial_execution_identity(p_scan,p_context->>'assignment_digest',value);
 grant_value:=p_grant;
 profile:=p_context->'profile';
 IF value->'grant_id' IS DISTINCT FROM grant_value->'grant_id' OR value->'source_digest' IS DISTINCT FROM grant_value->'source_digest' OR jsonb_array_length(value->'entries')<>jsonb_array_length(a#>'{preparation,source_mapping}') THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 FOR item,n IN SELECT e,i::INTEGER-1 FROM jsonb_array_elements(value->'entries') WITH ORDINALITY v(e,i) LOOP
  mapping:=a#>ARRAY['preparation','source_mapping',n::TEXT]; source:=mapping->'source'; prepared:=item->'prepared';
  IF item->>'ordinal' IS DISTINCT FROM n::TEXT OR ((mapping->>'role'='raw_video') IS DISTINCT FROM (prepared='null'::JSONB)) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  IF prepared='null'::JSONB THEN CONTINUE; END IF;
  SELECT r INTO STRICT rule FROM jsonb_array_elements(profile#>'{spec,rules}') r WHERE r->>'role'=mapping->>'role';
  IF prepared->'transform' IS DISTINCT FROM source->'transform' OR prepared->'parameters' IS DISTINCT FROM source->'transform_parameters'
   OR (prepared#>>'{bytes,byte_count}')::BIGINT>(rule#>>'{limits,output_bytes}')::BIGINT OR prepared#>>'{bytes,content_type}' IS DISTINCT FROM (CASE WHEN source->>'kind'='audio' THEN 'audio/wav' ELSE source->>'source_content_type' END) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  IF (prepared->>'source_identity')::BOOLEAN OR source->>'kind'='image' THEN
   IF prepared->'bytes' IS DISTINCT FROM jsonb_build_object('byte_count',source->'source_byte_count','sha256',source->'source_sha256','content_type',source->'source_content_type') OR NOT (prepared->>'source_identity')::BOOLEAN THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  END IF;
  total:=total+(prepared#>>'{bytes,byte_count}')::BIGINT;
 END LOOP;
 IF total>(profile#>>'{spec,limits,output_bytes}')::BIGINT THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
END; $$;
CREATE FUNCTION internal.assert_initial_qualified_resolved(p_scan UUID,p_context JSONB,p_output JSONB,p_text TEXT) RETURNS VOID LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE value JSONB; entries JSONB; item JSONB; prepared JSONB; source_id UUID; n INTEGER; object UUID; seen UUID[]:=ARRAY[]::UUID[];
BEGIN
 value:=internal.parse_initial_preparation_execution('resolved_manifest',p_text); entries:=p_output->'entries';
 PERFORM internal.assert_initial_execution_identity(p_scan,p_context->>'assignment_digest',value);
 IF value->>'request_digest' IS DISTINCT FROM internal.initial_preparation_execution_digest('output_manifest',internal.initial_canonical(p_output)) OR value->'grant_id' IS DISTINCT FROM p_output->'grant_id' OR jsonb_array_length(value->'entries')<>jsonb_array_length(entries) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
 FOR item,n IN SELECT e,i::INTEGER-1 FROM jsonb_array_elements(value->'entries') WITH ORDINALITY v(e,i) LOOP
  prepared:=entries->n->'prepared'; object:=(item->>'object_id')::UUID;
  IF item->>'ordinal' IS DISTINCT FROM n::TEXT OR ((prepared='null'::JSONB) IS DISTINCT FROM (object IS NULL)) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  IF object IS NULL THEN CONTINUE; END IF;
  source_id:=(p_context#>>ARRAY['assignment','preparation','source_mapping',n::TEXT,'object_id'])::UUID;
  IF object=ANY(seen) OR ((prepared->>'source_identity')::BOOLEAN AND object<>source_id) OR (NOT (prepared->>'source_identity')::BOOLEAN AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_context#>'{assignment,preparation,source_mapping}') m WHERE (m->>'object_id')::UUID=object)) THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
  seen:=array_append(seen,object);
 END LOOP;
END; $$;
CREATE FUNCTION internal.assert_initial_qualified_outcome(p_scan UUID,p_context JSONB,p_expiry NUMERIC,p_text TEXT) RETURNS VOID LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
DECLARE v JSONB:=internal.parse_initial_qualified_codec('outcome',p_text); source_digest TEXT; retained JSONB;
BEGIN
 PERFORM internal.assert_initial_execution_identity(p_scan,p_context->>'assignment_digest',jsonb_set(v,'{version}','1'));
 PERFORM internal.assert_initial_qualified_source(p_scan,p_context,internal.initial_canonical(v->'source_verification'));
 source_digest:=internal.initial_preparation_execution_digest('source_verification',internal.initial_canonical(v->'source_verification'));
 PERFORM internal.assert_initial_qualified_grant(p_scan,p_context,source_digest,p_expiry,internal.initial_canonical(v->'grant'));
 PERFORM internal.assert_initial_qualified_output(p_scan,p_context,v->'grant',internal.initial_canonical(v->'output_manifest'));
 PERFORM internal.assert_initial_qualified_resolved(p_scan,p_context,v->'output_manifest',internal.initial_canonical(v->'resolved_manifest'));
 SELECT COALESCE(jsonb_agg(jsonb_build_object('ordinal',e->'ordinal','object_id',v#>ARRAY['resolved_manifest','entries',(i-1)::TEXT,'object_id'],'bytes',e#>'{prepared,bytes}') ORDER BY i),'[]'::JSONB) INTO retained FROM jsonb_array_elements(v#>'{output_manifest,entries}') WITH ORDINALITY x(e,i) WHERE e->'prepared'<>'null'::JSONB;
 IF v->'profile' IS DISTINCT FROM p_context->'profile' OR v->'retained' IS DISTINCT FROM retained THEN RAISE EXCEPTION 'initial_analysis_input_invalid' USING ERRCODE='22023'; END IF;
END; $$;
CREATE FUNCTION internal.initial_qualified_outcome_digest(p_text TEXT) RETURNS TEXT LANGUAGE PLPGSQL STABLE SET search_path='' AS $$
BEGIN
 PERFORM internal.parse_initial_qualified_codec('outcome',p_text);
 RETURN encode(extensions.digest(convert_to('merian.initial-analysis.preparation-execution.outcome.v2'||chr(10)||p_text,'UTF8'),'sha256'),'hex');
END; $$;
REVOKE ALL ON FUNCTION internal.initial_qualified_schema(),internal.parse_initial_qualified_codec(TEXT,TEXT),internal.initial_qualified_context(TEXT,TEXT,TEXT,TEXT,TEXT,TEXT),internal.assert_initial_qualified_grant(UUID,JSONB,TEXT,NUMERIC,TEXT),internal.assert_initial_qualified_source(UUID,JSONB,TEXT),internal.assert_initial_qualified_output(UUID,JSONB,JSONB,TEXT),internal.assert_initial_qualified_resolved(UUID,JSONB,JSONB,TEXT),internal.assert_initial_qualified_outcome(UUID,JSONB,NUMERIC,TEXT),internal.initial_qualified_outcome_digest(TEXT) FROM PUBLIC,anon,authenticated,service_role;
RESET lock_timeout;
RESET statement_timeout;
